update public.games set release_date='2026-11-19', description='Grand Theft Auto VI القادمة في 19 نوفمبر 2026 بحسب Rockstar Games. استكشف ولاية Leonida وVice City مع جيسون ولوسيا. الصور ترويجية أو لقطات من العروض الرسمية؛ وليست صور لعب مستقلة بعد.', cover_url='https://i.ytimg.com/vi/QdBZY2fkU-0/maxresdefault.jpg', backdrop_url='https://sinetopya.com/content/images/2026/08/gta-6-.jpg', gallery_urls=array['https://sinetopya.com/content/images/2026/08/gta-6-.jpg','https://resizer.ladbiblegroup.com/ogimage/v3/assets/bltbc1876152fcd9f07/blt7e4ce4816f194745/6a8ea8c0fa24349c9c1ccf04/gta-6-day-cycle.jpg','https://i.ytimg.com/vi/VQRLujxTm3c/maxresdefault.jpg']::text[], trailer_id='VQRLujxTm3c', updated_at=now() where slug='gta-vi';
update public.games set release_date='2020-05-19', description='نسخة Definitive Edition المحسّنة من Mafia II الصادرة في 19 مايو 2020. تابع فيتو سكاليتا وجو في Empire Bay خلال الأربعينيات والخمسينيات في قصة عن عالم المافيا.', cover_url='https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/1030830/header.jpg', backdrop_url='https://multiplayer.net-cdn.it/thumbs/images/2020/05/19/20200519133009_1_jpg_1400x0_q85.jpg', gallery_urls=array['https://multiplayer.net-cdn.it/thumbs/images/2020/05/19/20200519133009_1_jpg_1400x0_q85.jpg','https://www.gamesload.com/images/products/2kgames/nxw5ebe4d3d131ea.jpg']::text[], trailer_id='8BPUGkxTVdg', updated_at=now() where slug='mafia-ii';
update public.games set release_date='2025-11-14', description='تدور أحداث Call of Duty: Black Ops 7 في عام 2035. تجمع اللعبة بين طور قصة تعاوني، ومواجهات جماعية مستقبلية، وطور زومبي بجولات.', cover_url='https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/3606480/header.jpg', backdrop_url='https://cdn.mos.cms.futurecdn.net/ERWHrJnW3xSK8Zwiw7o3jX.jpg', gallery_urls=array['https://cdn.mos.cms.futurecdn.net/ERWHrJnW3xSK8Zwiw7o3jX.jpg','https://www.4fansites.de/bilder/news/call-of-duty-black-ops-7-zombie-guide-m.webp']::text[], trailer_id='9txkGBj_trg', updated_at=now() where slug='black-ops-7';
update public.games set release_date='2023-11-10', description='إصدار Modern Warfare III لعام 2023؛ تواصل Task Force 141 مواجهة فلاديمير ماكاروف، وتضم اللعبة طور القصة واللعب الجماعي والزومبي. ليست نسخة 2011.', cover_url='https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/3595270/header.jpg', backdrop_url='https://cdn.cgmagonline.com/wp-content/uploads/2023/11/call-of-duty-modern-warfare-iii-ps5-review-2023-11-14_14-20-41_593716.jpg', gallery_urls=array['https://cdn.cgmagonline.com/wp-content/uploads/2023/11/call-of-duty-modern-warfare-iii-ps5-review-2023-11-14_14-20-41_593716.jpg','https://img.playstationtrophies.org/images/monthly_2024_06/screenshots/23197/mwiii-s4r-announcement-018_bdfad842-3f3b-43ff-956d-41ef9fe007d2.jpg']::text[], trailer_id='mHDEDDrGYvo', updated_at=now(), developer='Sledgehammer Games / Infinity Ward' where slug='modern-warfare-iii';
update public.games set release_date='2013-09-17', description='انطلق في عالم Los Santos وBlaine County مع مايكل وفرانكلين وتريفور عبر المهمات والسرقات والقيادة في عالم مفتوح. تاريخ الإصدار الأصلي 17 سبتمبر 2013.', cover_url='https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/271590/header.jpg', backdrop_url='https://www.igrandtheftauto.com/content/images/4288-gta5-franklin-leads-the-pack.jpg', gallery_urls=array['https://www.igrandtheftauto.com/content/images/4288-gta5-franklin-leads-the-pack.jpg','https://www.gtavision.com/images/newspics/gta-v-gta-online-pc-4k-screenshots_15_27022015.jpg','https://images-cdn.ubuy.co.in/650ed966b5ef98409e10bbda-pc.jpg']::text[], trailer_id='hvoD7ehZPcM', updated_at=now() where slug='gta-v';
update public.games set release_date='2018-10-26', description='عِش قصة آرثر مورغان وعصابة فان دير ليند في أمريكا عام 1899. لعبة عالم مفتوح ذات تفاصيل واسعة عن البقاء والوفاء ونهاية عصر الغرب المتوحش.', cover_url='https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/1174180/header.jpg', backdrop_url='https://img.redbull.com/images/c_limit%2Cw_1500%2Ch_1000/f_auto%2Cq_auto/redbullcom/2018/10/30/82244891-dfee-49d4-a75d-1478f41de281/red-dead-redemption-2-horse', gallery_urls=array['https://img.redbull.com/images/c_limit%2Cw_1500%2Ch_1000/f_auto%2Cq_auto/redbullcom/2018/10/30/82244891-dfee-49d4-a75d-1478f41de281/red-dead-redemption-2-horse','https://img.redbull.com/images/q_auto%2Cf_auto/redbullcom/2018/08/13/4dbc9a82-0b9c-49b4-80c6-2da4cc2546df/rdr2-konfrontationen']::text[], trailer_id='eaW0tYpxyp0', updated_at=now() where slug='red-dead-redemption-2';
update public.games set release_date='2022-02-25', description='لعبة تقمص أدوار وعالم مفتوح من FromSoftware؛ استكشف The Lands Between، وواجه الزعماء وطوّر شخصيتك في رحلة نحو لقب Elden Lord.', cover_url='https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/1245620/header.jpg', backdrop_url='https://www.game.guide/images/elden-ring/best-elden-ring-progression-route-best-elden-ring-progression-route-8-1024x576.png', gallery_urls=array['https://www.game.guide/images/elden-ring/best-elden-ring-progression-route-best-elden-ring-progression-route-8-1024x576.png','https://i.guim.co.uk/img/media/8301b3d33934aaa4586d173ce43a603af105f8ee/67_0_3600_2160/master/3600.jpg?auto=format&fit=max&quality=85&s=9c14dcba1cee69bc7b0e8cf3e78a57b4&width=700']::text[], trailer_id='qqiC88f9ogU', updated_at=now(), publisher='Bandai Namco Entertainment' where slug='elden-ring';
update public.games set release_date='2021-11-09', description='شارك في مهرجان Horizon بالمكسيك؛ سباقات مفتوحة بين الصحاري والشواطئ والغابات. صدرت أولًا في 9 نوفمبر 2021 لـXbox والحاسوب، ووصلت لاحقًا إلى PS5.', cover_url='https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/1551360/header.jpg', backdrop_url='https://imagenes.20minutos.es/files/image_1920_1080/uploads/imagenes/2021/11/11/forza-horizon-5.png', gallery_urls=array['https://imagenes.20minutos.es/files/image_1920_1080/uploads/imagenes/2021/11/11/forza-horizon-5.png','https://images.purexbox.com/screenshots/118488/large.jpg','https://cdn.mos.cms.futurecdn.net/8bYLittjksxH8RxtaL8Q9B-1920-80.jpg']::text[], trailer_id='U3mEOHvSUyw', updated_at=now() where slug='forza-horizon-5';
update public.games set release_date='2020-12-10', description='لعبة تقمص أدوار في Night City؛ العب بشخصية V في مدينة مستقبلية مليئة بالمهام والخيارات وتعديلات الجسد. تاريخ الإصدار الأصلي 10 ديسمبر 2020.', cover_url='https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/1091500/header.jpg', backdrop_url='https://imagenes.hobbyconsolas.com/files/image_1920_1080/uploads/imagenes/2023/04/25/69027a96bc72c.jpeg', gallery_urls=array['https://imagenes.hobbyconsolas.com/files/image_1920_1080/uploads/imagenes/2023/04/25/69027a96bc72c.jpeg','https://cdn.alza.sk/Foto/ImgGalery/Image/cyberpunk-2077-recenze-city-streets.jpg']::text[], trailer_id='UnA7tepsc7s', updated_at=now() where slug='cyberpunk-2077';
